<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'سفارش‌های من'});const{api}=useShopApi();const{data}=await useAsyncData('my-orders',()=>api<any>('/profile/orders'));const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v);const labels:any={pending:'در انتظار پرداخت',confirmed:'تأییدشده',processing:'در حال آماده‌سازی',shipped:'ارسال‌شده',delivered:'تحویل‌شده',cancelled:'لغوشده',returned:'مرجوع‌شده'}</script>
<template><div class="mx-auto max-w-5xl px-4 py-10"><div class="flex items-center justify-between"><h1 class="text-2xl font-black">سفارش‌های من</h1><NuxtLink to="/profile" class="text-sm font-bold text-brand-700">بازگشت به حساب</NuxtLink></div><div class="mt-7 space-y-4"><article v-for="o in data?.data" :key="o.id" class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="font-black">سفارش {{o.number}}</p><p class="mt-2 text-xs text-slate-400">{{new Date(o.created_at).toLocaleDateString('fa-IR')}} • {{o.items_count}} کالا</p></div><span class="rounded-lg bg-amber-50 px-3 py-1.5 text-xs font-bold text-amber-700">{{labels[o.status]}}</span></div><div class="mt-5 flex items-end justify-between border-t pt-4"><p class="text-sm text-slate-500">مبلغ سفارش: <strong class="text-slate-900">{{money(o.payable_amount)}} تومان</strong></p><NuxtLink :to="`/profile/orders/${o.id}`" class="text-sm font-bold text-brand-700">جزئیات سفارش ←</NuxtLink></div></article><div v-if="!data?.data?.length" class="rounded-2xl border border-dashed bg-white p-14 text-center text-slate-400">هنوز سفارشی ثبت نکرده‌اید.</div></div></div></template>
